krpano.action:
if(%1,
	if(!gal_built, gallery_build(); );
	set(layer[gal_bg].visible,    true);
	set(layer[gal_box].visible,   true);
	set(layer[gal_title].visible, true);
	set(layer[gal_close].visible, true);
	set(layer[gal_bg].alpha, 0);
	tween(layer[gal_bg].alpha, 1.0, 0.25);
,
	tween(layer[gal_bg].alpha, 0.0, 0.2, default,
		set(layer[gal_bg].visible,    false);
		set(layer[gal_box].visible,   false);
		set(layer[gal_title].visible, false);
		set(layer[gal_close].visible, false);
	);
);

set(gal_built, true);


if(device.mobile,
	set(gal_cols, 3);  set(gal_iw, 108); set(gal_ih, 92);  set(gal_th, 66);
,
	set(gal_cols, 5);  set(gal_iw, 184); set(gal_ih, 148); set(gal_th, 112);
);

set(gal_n, 0);

for(set(i,0), i LT scene.count, inc(i),


	mod(gal_c, gal_n, gal_cols);
	calc(gal_r, (gal_n - gal_c) / gal_cols);

	calc(gal_x, gal_c * gal_iw);
	calc(gal_y, gal_r * gal_ih);

	txtadd(gal_item, 'galitem_', get(i));
	addlayer(get(gal_item));
	set(layer[get(gal_item)].parent,     gal_scroll);
	set(layer[get(gal_item)].type,       container);
	set(layer[get(gal_item)].align,      lefttop);
	set(layer[get(gal_item)].x,          get(gal_x));
	set(layer[get(gal_item)].y,          get(gal_y));
	set(layer[get(gal_item)].width,      calc(gal_iw - 12));
	set(layer[get(gal_item)].height,     calc(gal_ih - 12));
	set(layer[get(gal_item)].bgcolor,    0xFFFFFF);
	set(layer[get(gal_item)].bgalpha,    0.06);
	set(layer[get(gal_item)].bgroundedge, 6);
	set(layer[get(gal_item)].handcursor, true);
	set(layer[get(gal_item)].maskchildren, true);
	calc(layer[get(gal_item)].onclick, 'gallery_goto(' + scene[get(i)].name + ');');
	set(layer[get(gal_item)].onover,  'tween(bgalpha,0.22);');
	set(layer[get(gal_item)].onout,   'tween(bgalpha,0.06);');


	txtadd(gal_img, 'galimg_', get(i));
	addlayer(get(gal_img));
	set(layer[get(gal_img)].parent,  get(gal_item));
	set(layer[get(gal_img)].align,   lefttop);
	set(layer[get(gal_img)].x,       0);
	set(layer[get(gal_img)].y,       0);
	set(layer[get(gal_img)].width,   '100%');
	set(layer[get(gal_img)].height,  get(gal_th));
	set(layer[get(gal_img)].enabled, false);
	copy(layer[get(gal_img)].url,    scene[get(i)].thumburl);


	txtadd(gal_txt, 'galtxt_', get(i));
	addlayer(get(gal_txt));
	set(layer[get(gal_txt)].parent,  get(gal_item));
	set(layer[get(gal_txt)].type,    text);
	set(layer[get(gal_txt)].align,   bottom);
	set(layer[get(gal_txt)].y,       4);
	set(layer[get(gal_txt)].bg,      false);
	set(layer[get(gal_txt)].enabled, false);
	set(layer[get(gal_txt)].css,     'color:#FFFFFF; font-family:Arial; font-size:11px;');
	copy(layer[get(gal_txt)].html,   scene[get(i)].title);

	inc(gal_n);
);


calc(gal_rows, ceil(gal_n / gal_cols));
set(layer[gal_scroll].width,  calc(gal_cols * gal_iw));
set(layer[gal_scroll].height, calc(gal_rows * gal_ih));
